// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title DatabaseDriver
 * @notice On-chain key-value store with graceful shutdown and type-safe encoding
 */
contract DatabaseDriver {
    enum FieldType { UINT256, ADDRESS, BYTES32, STRING }
    enum State { ACTIVE, DRAINING, SHUTDOWN }

    struct Record {
        FieldType ftype;
        bytes32 slot;
        uint256 timestamp;
        bool valid;
    }

    State public currentState;
    address public owner;
    uint256 public drainDeadline;
    uint256 public constant DRAIN_PERIOD = 1 hours;

    mapping(bytes32 => Record) private records;
    mapping(bytes32 => bytes) private rawStorage;
    mapping(address => bool) public operators;

    event RecordStored(bytes32 indexed key, FieldType ftype);
    event ShutdownInitiated(uint256 deadline);
    event ShutdownComplete();

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    modifier onlyOperator() {
        require(operators[msg.sender] || msg.sender == owner, "Not operator");
        _;
    }

    modifier whenActive() {
        require(currentState == State.ACTIVE, "Not active");
        _;
    }

    modifier whenNotShutdown() {
        require(currentState != State.SHUTDOWN, "Is shutdown");
        _;
    }

    constructor() {
        owner = msg.sender;
        currentState = State.ACTIVE;
        operators[msg.sender] = true;
    }

    function addOperator(address op) external onlyOwner {
        operators[op] = true;
    }

    function initiateShutdown() external onlyOwner whenActive {
        currentState = State.DRAINING;
        drainDeadline = block.timestamp + DRAIN_PERIOD;
        emit ShutdownInitiated(drainDeadline);
    }

    function completeShutdown() external onlyOwner {
        require(currentState == State.DRAINING, "Not draining");
        require(block.timestamp >= drainDeadline, "Drain period active");
        currentState = State.SHUTDOWN;
        emit ShutdownComplete();
    }

    function storeUint256(bytes32 key, uint256 value) external onlyOperator whenActive {
        records[key] = Record(FieldType.UINT256, keccak256(abi.encode(key, value)), block.timestamp, true);
        rawStorage[key] = abi.encode(value);
        emit RecordStored(key, FieldType.UINT256);
    }

    function storeAddress(bytes32 key, address value) external onlyOperator whenActive {
        records[key] = Record(FieldType.ADDRESS, keccak256(abi.encode(key, value)), block.timestamp, true);
        rawStorage[key] = abi.encode(value);
        emit RecordStored(key, FieldType.ADDRESS);
    }

    function storeBytes32(bytes32 key, bytes32 value) external onlyOperator whenActive {
        records[key] = Record(FieldType.BYTES32, keccak256(abi.encode(key, value)), block.timestamp, true);
        rawStorage[key] = abi.encode(value);
        emit RecordStored(key, FieldType.BYTES32);
    }

    /**
     * @notice Retrieve a record with type verification during drain period
     * @dev Type safety is always enforced regardless of state
     */
    function retrieveAs(bytes32 key, FieldType expectedType) external view whenNotShutdown returns (bytes memory) {
        Record storage rec = records[key];
        require(rec.valid, "Record not found");

        // Type checking: enforce strict typing in ALL states
        _enforceTypeCompat(rec.ftype, expectedType);

        return rawStorage[key];
    }

    /**
     * @notice Safe retrieval that always enforces type checking
     */
    function retrieveStrict(bytes32 key, FieldType expectedType) external view whenNotShutdown returns (bytes memory) {
        Record storage rec = records[key];
        require(rec.valid, "Record not found");
        _enforceTypeCompat(rec.ftype, expectedType);
        return rawStorage[key];
    }

    function _enforceTypeCompat(FieldType stored, FieldType requested) internal pure {
        if (stored == requested) return;
        // Allow uint256 <-> bytes32 coercion (same size, safe)
        if (stored == FieldType.UINT256 && requested == FieldType.BYTES32) return;
        if (stored == FieldType.BYTES32 && requested == FieldType.UINT256) return;
        revert("Type mismatch");
    }

    function getRecordMeta(bytes32 key) external view returns (FieldType, uint256, bool) {
        Record storage rec = records[key];
        return (rec.ftype, rec.timestamp, rec.valid);
    }

    function decodeAsAddress(bytes memory data) external pure returns (address) {
        return abi.decode(data, (address));
    }

    function decodeAsUint256(bytes memory data) external pure returns (uint256) {
        return abi.decode(data, (uint256));
    }
}
